//! Embedded WOFF font data for HTML export (subsetted to 16 ramp characters)

/// Subsetted WOFF font data for unscii-8 (base64 encoded)
pub const UNSCII8_WOFF_BASE64: &str = "";

/// Subsetted WOFF font data for unscii-16 (base64 encoded)
pub const UNSCII16_WOFF_BASE64: &str = "";

/// Get the base64 WOFF font data for a given font variant
pub fn get_font_woff_base64(variant: crate::font::variants::FontVariant) -> &'static str {
    match variant {
        crate::font::variants::FontVariant::Unscii16 => UNSCII16_WOFF_BASE64,
        _ => UNSCII8_WOFF_BASE64, // All 8x8 variants use unscii-8 subset
    }
}

/// Get the WOFF format string for a given font variant
pub fn get_font_woff_format(_variant: crate::font::variants::FontVariant) -> &'static str {
    "woff"
}

/// Get the font family name for CSS
pub fn get_font_family_name(variant: crate::font::variants::FontVariant) -> &'static str {
    match variant {
        crate::font::variants::FontVariant::Unscii8 => "Unscii8",
        crate::font::variants::FontVariant::Unscii8Alt => "Unscii8Alt",
        crate::font::variants::FontVariant::Unscii8Fantasy => "Unscii8Fantasy",
        crate::font::variants::FontVariant::Unscii8Mcr => "Unscii8Mcr",
        crate::font::variants::FontVariant::Unscii8Tall => "Unscii8Tall",
        crate::font::variants::FontVariant::Unscii8Thin => "Unscii8Thin",
        crate::font::variants::FontVariant::Unscii16 => "Unscii16",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_font_base64_not_empty() {
        assert!(!UNSCII8_WOFF_BASE64.is_empty());
        assert!(!UNSCII16_WOFF_BASE64.is_empty());
    }

    #[test]
    fn test_get_font_woff_base64() {
        assert_eq!(get_font_woff_base64(crate::font::variants::FontVariant::Unscii8), UNSCII8_WOFF_BASE64);
        assert_eq!(get_font_woff_base64(crate::font::variants::FontVariant::Unscii16), UNSCII16_WOFF_BASE64);
        assert_eq!(get_font_woff_base64(crate::font::variants::FontVariant::Unscii8Alt), UNSCII8_WOFF_BASE64);
    }

    #[test]
    fn test_get_font_family_name() {
        assert_eq!(get_font_family_name(crate::font::variants::FontVariant::Unscii8), "Unscii8");
        assert_eq!(get_font_family_name(crate::font::variants::FontVariant::Unscii16), "Unscii16");
    }
}